using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SchoolERP.Domain.Entities;
namespace SchoolERP.Infrastructure.Persistence.Configurations;public sealed class ClassSectionConfiguration:IEntityTypeConfiguration<ClassSection>{public void Configure(EntityTypeBuilder<ClassSection>b){b.ToTable("class_sections",t=>{t.HasCheckConstraint("ck_class_sections_order","display_order >= 0");t.HasCheckConstraint("ck_class_sections_capacity","capacity IS NULL OR (capacity BETWEEN 1 AND 500)");t.HasCheckConstraint("ck_class_sections_status","status BETWEEN 1 AND 4");});b.ConfigureAudit();b.Property(x=>x.TenantId).HasColumnName("tenant_id");b.Property(x=>x.SchoolId).HasColumnName("school_id");b.Property(x=>x.AcademicYearId).HasColumnName("academic_year_id");b.Property(x=>x.SchoolClassId).HasColumnName("school_class_id");b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(100).IsRequired();b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50).IsRequired();b.Property(x=>x.ShortName).HasColumnName("short_name").HasMaxLength(50);b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.Property(x=>x.Capacity).HasColumnName("capacity");b.Property(x=>x.RoomNumber).HasColumnName("room_number").HasMaxLength(100);b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(500);b.Property(x=>x.Status).HasColumnName("status").HasConversion<int>();b.Property(x=>x.ActivatedAt).HasColumnName("activated_at");b.Property(x=>x.DeactivatedAt).HasColumnName("deactivated_at");b.Property(x=>x.ArchivedAt).HasColumnName("archived_at");b.HasOne(x=>x.Tenant).WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.School).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.AcademicYear).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.SchoolClass).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.SchoolClassId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.TenantId);b.HasIndex(x=>x.SchoolId);b.HasIndex(x=>x.AcademicYearId);b.HasIndex(x=>x.SchoolClassId);b.HasIndex(x=>new{x.SchoolClassId,x.Code}).IsUnique().HasDatabaseName("ux_class_sections_class_code");b.HasIndex(x=>new{x.SchoolClassId,x.Status});b.HasIndex(x=>new{x.SchoolClassId,x.DisplayOrder});}}
